from pathlib import Path
p=Path('/home/ubuntu/co08-ssh-hosts/client/src/pages/Home.tsx')
s=p.read_text()
start=s.index('function HostsCard')
end=s.index('function ActivityCard')
new='''function HostsCard({ hosts, onDelete, onRenew }: any) { return <Card className="border-white/10 bg-white/[0.035]"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="text-lg text-white">Host inventory</CardTitle><p className="mt-1 text-sm text-slate-400">Individual A records managed in the configured zone.</p></div><Badge variant="outline" className="border-white/10 text-slate-300">{hosts.length} shown</Badge></CardHeader><CardContent>{hosts.length === 0 ? <div className="rounded-lg border border-dashed border-white/10 py-12 text-center text-sm text-slate-500">No hosts yet. Create your first secure alias above.</div> : <div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="border-b border-white/10 text-[10px] uppercase tracking-[0.18em] text-slate-500"><tr><th className="px-4 py-3">Hostname</th><th className="px-4 py-3">VPS IP</th><th className="px-4 py-3">Created</th><th className="px-4 py-3">Expires</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Actions</th></tr></thead><tbody className="divide-y divide-white/[0.06]">{hosts.map((h: any) => <tr key={h.id} className="hover:bg-white/[0.025]"><td className="px-4 py-4 font-mono text-cyan-200">{h.hostname}<div className="mt-1 text-xs text-slate-500">ssh root@{h.hostname}</div></td><td className="px-4 py-4 font-mono text-slate-300">{h.ip}</td><td className="px-4 py-4 text-xs text-slate-400">{formatDate(h.createdAt)}</td><td className="px-4 py-4 text-xs text-slate-400">{formatDate(h.expiresAt)}</td><td className="px-4 py-4"><Badge className={h.status === "active" ? "border border-emerald-300/20 bg-emerald-300/10 text-emerald-300" : "border border-amber-300/20 bg-amber-300/10 text-amber-300"}>{h.status}</Badge></td><td className="px-4 py-4"><div className="flex gap-2"><Button size="icon" variant="outline" title="Copy hostname" className="border-white/10 bg-transparent text-slate-300" onClick={() => copy(h.hostname)}><Link2 className="h-4 w-4"/></Button><Button size="icon" variant="outline" title="Copy SSH command" className="border-white/10 bg-transparent text-slate-300" onClick={() => copy(`ssh root@${h.hostname}`)}><Copy className="h-4 w-4"/></Button>{h.status === "active" && <Button size="icon" variant="outline" title="Renew" className="border-white/10 bg-transparent text-slate-300" onClick={() => onRenew(h.id)}><RefreshCw className="h-4 w-4"/></Button>}<Button size="icon" variant="outline" title="Delete DNS record" className="border-red-300/10 bg-transparent text-red-300" onClick={() => onDelete(h.id)}><Trash2 className="h-4 w-4"/></Button></div></td></tr>)}</tbody></table></div>}</CardContent></Card> }
'''
p.write_text(s[:start]+new+s[end:])
